 "content": "def transform(grid):
    """Copy each boundary motif into rows at marker-colored anchor positions."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    motifs = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            colors = []
            while c < w and grid[r][c] != 0:
                colors.append(grid[r][c])
                c += 1
            motifs.append((start, colors))
    color_positions = {}
    for start, colors in motifs:
        for i, color in enumerate(colors):
            color_positions.setdefault(color, []).append((colors, i))
    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            matches = color_positions.get(color, [])
            if color == 0 or not matches:
                continue
            colors, index = matches[0]
            left = c - index
            for i, value in enumerate(colors):
                cc = left + i
                if 0 <= cc < w:
                    out[r][cc] = value
    return out
